<?php defined('SNAPSMACK_SKIN_RENDER') || exit; ?>
<!doctype html><html lang="<?php echo snap_escape_attr($view['site']['language']); ?>" dir="<?php echo snap_escape_attr($view['site']['direction']); ?>">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo snap_escape_html($view['response']['page_title'] ?? $view['site']['site_name']); ?></title><link rel="stylesheet" href="<?php echo snap_escape_url($view['site']['base_style_url'] ?? ''); ?>"><link rel="stylesheet" href="<?php echo snap_escape_url($view['site']['skin_style_url']); ?>"><?php echo snap_render_html($view['site']['skin_custom_style'] ?? ''); ?><?php echo snap_render_html($view['site']['skin_presentation']['style'] ?? ''); ?></head>
<body class="galleria-v2"><header id="header" class="site-header htbs-header"><div class="inside"><a class="site-title logo-area" href="<?php echo snap_route_url('home'); ?>"><span class="site-title-text"><?php echo snap_escape_html($view['site']['site_name']); ?></span></a><?php echo snap_render_html(snap_render_component('navigation', ['items' => $view['response']['navigation'] ?? []])); ?></div></header>
<?php /* .htbs-single is what hides the navigation bar on a solo page --
   `.htbs-single #infobox { display: none }`, which both this skin and its
   fork have carried since before the conversion. It is only correct while
   the page HAS other navigation. 0.7.910D emitted it unconditionally, and on
   a site with htbs_show_filmstrip off that left the solo page with no
   navigation at all: bar hidden, no filmstrip, and in 912D no overlay
   either. Measured on hekeepsdroningon.ca. So the class now depends on the
   filmstrip actually being there; with no filmstrip the bar stays visible. */ ?>
<main id="scroll-stage" class="public-content<?php echo in_array($view['response']['kind'] ?? '', ['photo','post','collection'], true) ? ' htbs-single' : ''; ?><?php echo !empty($view['response']['filmstrip']) ? ' has-filmstrip' : ''; ?>">
<?php if (($view['response']['kind'] ?? '') === 'page'): ?><?php echo snap_render_html(snap_render_component('static-page', ['item' => $view['response']['item'] ?? [], 'page_title' => $view['response']['page_title'] ?? '', 'rendered_content' => $view['response']['rendered_content'] ?? '',])); ?><?php elseif (($view['response']['kind'] ?? '') === 'photo' || ($view['response']['kind'] ?? '') === 'post' || ($view['response']['kind'] ?? '') === 'collection'): ?>
<article id="photobox" class="h-entry single-image-page"><h1 class="p-name photo-title-footer sr-only"><?php echo snap_escape_html($view['response']['item']['img_title'] ?? $view['response']['item']['title'] ?? $view['response']['item']['name'] ?? ''); ?></h1><?php if (!empty($view['response']['item']['img_date']) || !empty($view['response']['item']['created_at'])): ?><time class="dt-published sr-only" datetime="<?php echo snap_escape_attr($view['response']['item']['img_date'] ?? $view['response']['item']['created_at']); ?>"><?php echo snap_escape_html($view['response']['item']['date_display'] ?? $view['response']['item']['img_date'] ?? $view['response']['item']['created_at']); ?></time><?php endif; ?><?php if (!empty($view['site']['owner_name'])): ?><span class="p-author h-card sr-only"><span class="p-name"><?php echo snap_escape_html($view['site']['owner_name']); ?></span></span><?php endif; ?>
<?php if (!empty($view['response']['item']['img_file']) || !empty($view['response']['item']['featured_image_path'])): ?><div class="htbs-gallery-room"><div class="frame-mount" data-bevel="<?php echo snap_escape_attr($view['site']['skin_presentation']['options']['htbs_bevel_style'] ?? ''); ?>" data-wood-grain="<?php echo snap_escape_attr($view['site']['skin_presentation']['options']['htbs_wood_grain'] ?? ''); ?>"><div class="frame-border"><div class="frame-mat"><div class="frame-bevel"><div class="frame-image u-photo post-image-wrap"><?php echo snap_render_html(snap_render_component('image', ['url' => $view['response']['item']['img_file'] ?? $view['response']['item']['featured_image_path'], 'alt' => $view['response']['item']['img_alt'] ?? $view['response']['item']['img_title'] ?? '', 'class' => 'post-image'])); ?></div></div></div></div></div></div><?php endif; ?>
</article><div id="infobox"><?php echo snap_render_html(snap_render_component('photo-navigation', ['item' => $view['response']['item'] ?? [],'previous' => $view['response']['previous'] ?? [],'first' => $view['response']['first'] ?? [],'last' => $view['response']['last'] ?? [],'next' => $view['response']['next'] ?? [],'comments' => $view['response']['comments'] ?? [],'comments_enabled' => $view['response']['comments_enabled'] ?? true,])); ?></div><?php if (!empty($view['response']['filmstrip'])): ?><div class="htbs-filmstrip"><?php foreach ($view['response']['filmstrip'] as $fi): ?><a class="htbs-filmstrip-item<?php echo (int)($fi['id'] ?? 0) === (int)($view['response']['item']['id'] ?? -1) ? ' active' : ''; ?>" href="<?php echo snap_escape_url(snap_route_url('photo', ['slug' => $fi['img_slug'] ?? ''])); ?>" title="<?php echo snap_escape_attr($fi['img_title'] ?? ''); ?>"><?php echo snap_render_html(snap_render_component('image', ['url' => $fi['img_thumb_square'] ?? $fi['img_file'] ?? '', 'alt' => $fi['img_title'] ?? ''])); ?></a><?php endforeach; ?></div><?php endif; ?>
<?php /* The INFO / SIGNALS overlay. assets/js/ss-engine-overlay.js documents
   this contract in its own header -- .htbs-tab[data-pane] and
   .htbs-pane#htbs-pane-{name} -- and galleria's manifest has loaded that
   engine as `smack-overlay` the whole time. The markup stopped being emitted
   at the strict conversion, so the engine bound nothing, 21 stylesheet rules
   matched nothing, and #show-details / #show-comments opened an empty
   drawer. style.css says where this belongs: "(Info & comments now rendered
   inside .htbs-overlay-box)". */ ?>
<div id="htbs-info-overlay" class="htbs-overlay"><div class="htbs-overlay-backdrop"></div><div class="htbs-overlay-box"><div class="htbs-overlay-tabs"><button type="button" class="htbs-tab active" data-pane="info">INFO</button><?php if (!empty($view['response']['comments_enabled'])): ?><button type="button" class="htbs-tab" data-pane="comments">SIGNALS</button><?php endif; ?><button type="button" class="htbs-overlay-close" title="Close">&times;</button></div><div class="htbs-overlay-content"><div id="htbs-pane-info" class="htbs-pane active"><div class="htbs-info-section"><div class="info-title-block"><div class="info-title"><?php echo snap_escape_html($view['response']['item']['img_title'] ?? $view['response']['item']['title'] ?? ''); ?></div><?php if (!empty($view['response']['item']['date_display']) || !empty($view['response']['item']['img_date'])): ?><div class="info-date"><?php echo snap_escape_html($view['response']['item']['date_display'] ?? $view['response']['item']['img_date']); ?></div><?php endif; ?></div><div class="description entry-content e-content static-transmission"><?php echo snap_render_html($view['response']['item']['content'] ?? $view['response']['item']['description'] ?? $view['response']['item']['img_description'] ?? ''); ?></div><?php if (!empty($view['response']['item']['exif'])): ?><div class="meta"><div class="meta-header">TECHNICAL SPECIFICATIONS</div><table class="htbs-exif-table exif-table"><?php foreach ($view['response']['item']['exif'] as $label => $value): ?><tr><td class="exif-label"><?php echo snap_escape_html($label); ?></td><td class="exif-value"><?php echo snap_escape_html($value); ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></div></div><?php if (!empty($view['response']['comments_enabled'])): ?><div id="htbs-pane-comments" class="htbs-pane"><?php echo snap_render_html(snap_render_component('comments', ['items' => $view['response']['comments'] ?? []])); ?></div><?php endif; ?></div></div></div>
<?php elseif (($view['response']['kind'] ?? '') === 'blogroll'): ?><section class="blogroll-page"><h1 class="blogroll-page-title"><?php echo snap_escape_html($view['response']['page_title'] ?? 'Blogroll'); ?></h1><?php echo snap_render_html(snap_render_component('blogroll', ['groups' => $view['response']['blogroll_groups'] ?? []])); ?></section>
<?php elseif (($view['response']['kind'] ?? '') === 'search'): ?><section class="search-results"><h1><?php echo snap_escape_html($view['response']['page_title'] ?? 'Search'); ?></h1><?php foreach (($view['response']['results'] ?? []) as $group): ?><?php foreach ($group as $item): ?><article><h2><?php echo snap_escape_html($item['img_title'] ?? $item['title'] ?? ''); ?></h2></article><?php endforeach; ?><?php endforeach; ?></section>
<?php elseif (($view['response']['kind'] ?? '') === 'landing'): ?><section class="htbs-slider-landing"><div class="htbs-slider-container"><div class="htbs-slider-wrapper"><div id="htbs-gallery-slider" class="ss-slider" data-auto-init data-per-view="1" data-speed="<?php echo snap_escape_attr($view['site']['skin_presentation']['options']['htbs_slider_speed'] ?? '800'); ?>" data-easing="ease-in-out" data-auto-advance="<?php if (($view['site']['skin_presentation']['options']['htbs_slider_auto'] ?? '0') === '1'): ?>true<?php else: ?>false<?php endif; ?>" data-auto-interval="5000" data-loop="<?php if (($view['site']['skin_presentation']['options']['htbs_slider_loop'] ?? '1') === '1'): ?>true<?php else: ?>false<?php endif; ?>"><div class="slider-track"><?php foreach (($view['response']['slider_items'] ?? []) as $item): ?><div class="slider-slide"><a class="htbs-slide-link" href="<?php echo snap_escape_url($item['url'] ?? snap_route_url('photo',['slug'=>$item['img_slug'] ?? ''])); ?>"><div class="frame-mount" data-bevel="<?php echo snap_escape_attr($view['site']['skin_presentation']['options']['htbs_bevel_style'] ?? ''); ?>" data-wood-grain="<?php echo snap_escape_attr($view['site']['skin_presentation']['options']['htbs_wood_grain'] ?? ''); ?>"><div class="frame-border"><div class="frame-mat"><div class="frame-bevel"><div class="frame-image"><?php echo snap_render_html(snap_render_component('image',['url'=>$item['img_file'] ?? $item['img_thumb_aspect'] ?? '','alt'=>$item['img_alt'] ?? $item['img_title'] ?? ''])); ?></div></div></div></div></div></a></div><?php endforeach; ?></div></div></div></div></section>
<?php elseif (($view['response']['kind'] ?? '') === 'archive' || ($view['response']['kind'] ?? '') === 'hashtag' || ($view['response']['kind'] ?? '') === 'albums' || ($view['response']['kind'] ?? '') === 'collections'): ?><section id="browse-grid" class="htbs-archive-grid public-grid h-feed archive-grid"><?php foreach (($view['response']['items'] ?? []) as $item): ?><a class="htbs-archive-item" href="<?php echo snap_escape_url($item['url'] ?? snap_route_url('photo',['slug'=>$item['img_slug'] ?? ''])); ?>"><div class="frame-mount"><div class="frame-border"><div class="frame-mat"><div class="frame-bevel"><div class="frame-image"><?php echo snap_render_html(snap_render_component('image',['url'=>$item['img_thumb_aspect'] ?? $item['img_thumb_square'] ?? $item['img_file'] ?? '','alt'=>$item['img_alt'] ?? $item['img_title'] ?? ''])); ?></div></div></div></div></div><div class="htbs-archive-title"><?php echo snap_escape_html($item['img_title'] ?? $item['title'] ?? ''); ?></div></a><?php endforeach; ?></section>
<?php else: ?><section class="not-found"><h1>Not found</h1></section><?php endif; ?>
</main>
<footer id="system-footer" class="site-footer<?php if (!empty($view['site']['footer']['lowercase'])): ?> footer-lowercase<?php endif; ?>"><div id="footer" class="inside"><?php echo snap_render_html(snap_render_component('footer', ['footer' => $view['site']['footer'] ?? []])); ?></div></footer><?php echo snap_render_html(snap_render_component('registered-assets', ['assets' => $view['site']['registered_assets'] ?? []])); ?><?php echo snap_render_html($view['site']['owner_custom_code'] ?? ''); ?>
</body></html>
